mapper.update:
update recycle_order
collector_id = #{collectorId}, status = #{status}, assign_type = #{assignType}, assign_time = #{assignTime}, accept_time = #{acceptTime}, arrive_time = #{arriveTime}, complete_time = #{completeTime}, brand_level = #{brandLevel}, usage_years = #{usageYears}, functional_status = #{functionalStatus}, appearance_level = #{appearanceLevel}, condition_factor = #{conditionFactor}, price_estimate = #{priceEstimate}, price_actual = #{priceActual}, points_earned = #{pointsEarned}, weight_actual = #{weightActual}, carbon_saved = #{carbonSaved}, cancel_reason = #{cancelReason}, user_rating = #{userRating}, user_comment = #{userComment}, collector_rating = #{collectorRating}, update_time = NOW()
where id = #{id}

mapper.select:
select * from recycle_order

    and user_id = #{userId}
    and collector_id = #{collectorId}
    and status = #{status}
    and order_no like concat('%', #{orderNo}, '%')
    and contact_phone = #{contactPhone}

order by create_time desc

select c.id, c.name, count(*) as orderCount, sum(r.price_actual) as totalAmount
from recycle_order r join collector c on r.collector_id = c.id
where r.status = 4 group by r.collector_id order by orderCount desc limit #{limit}

select id, status, version, order_no, user_id, collector_id
from recycle_order
where id = #{id}
